window.VD=window.VD||{};window.VD["audi/a3-8p"]={"a3-8p-facelift-activate-daytime-running-lights-in-odb":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate/deactivate the daytime running lights in the on-board computer (for models from 2008).  </p>\n<p><strong>Modification only possible for vehicles with a 30-byte module.  <br/></strong></p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>“, then on<strong>“Long Coding Helper</strong>“.</p>\n<p>5 – For models after <em>2008</em>: <br/> Byte<em> <strong>22</strong>: Bit <strong>1</strong>: Check “Daytime Running Lights (DRL) switchable via Menu”.</em></p>\n<p>For models after <em>2010/2011</em>:  </p>\n<p>Byte <strong>15</strong> Set bit <strong>7</strong></p>","a3-8p-facelift-corner-lights-activation":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose</strong>: Activating the <strong>cornering lights</strong> causes the fog light on the side toward which you’re turning the steering wheel to turn on when traveling at speeds below 50 km/h. This feature is also known as “cornering lights.” Once this feature is activated on your Audi A3, the fog light on the side of the turn you’re making will turn on! It’s super handy on narrow roads or in roundabouts.     </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>09 – Power Control Unit</strong>.”</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4-Activation-des-feux-en-virage-sur-Golf-5-et-6-f4e51c90.webp\"/></figure>\n<p><strong>6</strong> – In the window that appears, select  </p>\n<p><em>Byte <strong>14</strong>: </em><br/><em>Bit <strong>7</strong>: Check “Cornering Lights via Front Fog Lights active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5-Activation-de-la-fonction-Cornering-Lights-via-F-255e876b.webp\"/></figure>\n<p><strong>7</strong> – After completing this step, click on the “Exit” menu<br/>, then click “OK.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6-Activation-de-la-fonction-Cornering-Lights-via-F-2a08cc40.webp\"/></figure>","a3-8p-facelift-aps-radar-display-on-rns-e-screen":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose </strong>: to activate the display of Audi Parking System radars on the RNS-E screen.  </p>\n<p><strong><em>WARNING: requires RNS-E version 193 and rear + front radars  </em></strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>37 – Navigation</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding- 07</strong>”.  </p>\n<p><strong>5</strong> –  <em>Add <strong>2</strong> to the 3rd digit. (e.g. replace <strong>xx0xxxx</strong>by <strong>xx2xxxx</strong>) </em></p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click <strong>“10 – Parking Assistance</strong>,” then <strong> “Security -16</strong>” (code 71679)<br/><br/><strong>4 </strong>– Click <strong>“Coding – 07</strong>,” then<strong>“Long Coding</strong> Helper”</p>\n<p><strong>5</strong> – <em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check the “Optical illustration active” box</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RNSeaps-141b4bc9.webp\"/></figure>","a3-8p-facelift-change-rns-e-start-screen":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose </strong>: to change the screen display at RNS-E start-up.  </p>\n<p><strong><em><em>CAUTION (Some RNS-E settings are directly related to the selected model. It is not recommended to change the vehicle model (Line 1)). </em> </em></strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“37 – Navigation</strong>” .<br/><br/><strong>4 </strong>– Click on<strong>“Codage- 07</strong>”.</p>\n<p><strong>5</strong> – Change the 2nd digit to the desired model. (ex: replace<strong>02xxxxx</strong>by<strong>01xxxxx</strong>to display the Lamborghini logo on an A3) </p>\n<p>– 1 Lamborghini Galardo<br/>– 2 <em>Audi A3 (8P)</em><br/>– 3 Audi A4 (8E) or Seat Exeo (3R)<br/>– 4 Audi A4 Cabriolet (8H)<br/>– 5 Audi A6 (4B)<br/>– 6 Audi TT (8J)<br/>– 7 Audi R8 (42)</p>\n<p><strong>Line 2:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on<strong>“37 – Navigation</strong>” .<br/><br/> 4<strong>– </strong>Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 18</strong> (Start Screen) then set the value according to the desired display. <br/><br/>– 0 Standard<br/>– 1 Audi S3 (8P)<br/>– 2 Audi S4 (8E)<br/>– 3 Audi RS4, (8E)<br/>– 4 Audi TT (8J)<br/>– 5 Audi R8 (42)<br/>– 7 Audi TT S (8J)<br/>– 8 Audi TT RS (8J)<br/>– 9 Audi R8 GT (<em>42</em>)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-035-193-G_Module37_Adaptation_Channel18-4f78df82.webp\"/></figure>","a3-8p-facelift-coming-leaving-home-with-fog-lamps":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose: </strong>Enables fog lamps to be used for Coming Home and Leaving Home.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>17</strong>: Bit <strong>3</strong>: Check “Coming-Home (CH) via Fog-Light active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5_774-e325de60.webp\"/></figure>","a3-8p-facelift-coming-leaving-home-with-xenons":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose: </strong>Activates xenon headlamps instead of fog lamps for Coming Home and Leaving Home.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>17 </strong>:  </p>\n<p>Bit <strong>3</strong>: Uncheck “Coming-Home (CH) via Fog-Light active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5_774-e325de60.webp\"/></figure>","a3-8p-facelift-daytime-running-light-deactivation-drl-using-the-handbrake":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> to deactivate the daytime running lights (DRL) using the handbrake.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>“, then on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte<strong>“11</strong>”<br/>Then check Bit<strong>“0”</strong>.</p>","a3-8p-facelift-deactivate-windshield-washer-indicator":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose </strong>: to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07 </strong>”.  </p>\n<p><strong>5</strong> – <em>Subtract <strong>5 from the </strong>last coding digit (00xxxx<strong>?</strong>)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-A3-8P-ed05618a.webp\"/></figure>\n<p>Example: 0000148 -&gt; 0000143</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglaceaudia38p-d44c3cb7.webp\"/></figure>","a3-8p-facelift-disable-plate-light-control-odb-led-error":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> disables license plate light control. Useful when installing an LED bulb without resistance or an original Audi LED module.   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>23</strong>:  </p>\n<p>Bit <strong>6</strong>: Uncheck: “Lamp Monitoring (Cold) License Plate Lamps Active”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/led_plaque5-odt_147-d36567c5.webp\"/></figure>\n<p>And <em>Byte <strong>17 </strong>: </em><br/><em>Bit <strong>7</strong>: Uncheck “License Plate Light w/o Pulse Width Modulation (PWM) [LED Light]”.</em></p>\n<p>Or check Bit <strong>7</strong> if you are installing an original Audi LED module or if the error does not go away after clearing the fault for standard LEDs.</p>","a3-8p-facelift-door-lock-unlock-confirmation-beep":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose: </strong>Enables vehicle lock/unlock confirmation with beeps (alarm) and adds beep selection menu to ODB (MFA).  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><strong>6 – </strong> Select Byte <strong>5</strong>:</p>\n<p>Bit <strong>1</strong>: Check “Locking Confirmation via Horn Active”<br/>Bit <strong>4: </strong> Check “Unlocking Confirmation via Horn Active”</p>\n<p>To add the beep selection menu to the ODB (MFA):</p>\n<p>Bit <strong>2</strong>: Disable “<em> </em>” “<em>Horn Confirmation Adaptation Blocked (Adaptation Channel 010/011 &amp; MFA+/FIS)</em>“</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/horng6-2ffc7685.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/horng62-14ab4a90.webp\"/></figure>","a3-8p-facelift-flash-mode-lights-during-emergency-braking":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>16</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Emergency Brake Flashing via Brake Light active” (to activate brake lights)</em><br/><em>Bit <strong>2</strong>: Check “Emergency Brake Flashing via Turn Signal active” (to activate turn signals)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/emergencybreakg6-7e26fa37.webp\"/></figure>","a3-8p-facelift-gear-display-on-odb":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate the gear display on the on-board computer (for manual gearboxes).   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>10 – Adaptation</strong> </p>\n<p><strong>5</strong> – Select<strong> Channel 36</strong> <em>“Special Functions”</em><br/><em>Add <strong>+1</strong> to the existing value as specified in the tooltip (?xx).</em></p>\n<p><em><em>Example:</em></em> <em>original value 000: change to 100</em></p>\n<p>So excluding S/RS, the only possible value is: 100</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi-tt-rapport-4384918e.webp\"/></figure>","a3-8p-facelift-hill-hold-control":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose: Enables </strong>Hill Hold Control (Hill Start Assist).  </p>\n<p>Hill Hold Control maintains brake pressure for a few seconds after the brake pedal is held down for an extended period. (For after 2010) </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>03 – ABS Brakes</strong>” (or “<strong>03 – ABS Brakes” </strong>).<br/><br/><strong>4</strong> – Click “<strong>Coding – 07</strong>,” then “<strong>Long Coding Helper</strong>“</p>\n<p><em>Byte <strong>16 </strong>: </em><br/><em>Bit <strong>3</strong> (or 0 depending on model): Check “Hill Hold Control (HHC/PR-UG1/UG4) active/installed”.</em></p>\n<p><strong>Line 2: Hill Hold Control Settings.</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>03 – ABS Brakes</strong>” (or “<strong>03 – ABS Brakes” </strong>).<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”</p>\n<p>Select <strong>Channel 58</strong> (Hill Hold Control (HHC) from the drop-down list)</p>\n<p>Select a value:<br/>0 “normal”<br/>1 “earlier” (restarts with lower acceleration)<br/>2 “later” (restarts with higher acceleration)</p>","a3-8p-facelift-lap-timer":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> to add the stopwatch to the ODB (on-board computer).  </p>\n<p><strong><em>ATTENTION: Only for S3 and A3 Facelift compatible according to meter.</em></strong> </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>10 – Adaptation</strong> </p>\n<p><strong>5</strong> – Select<strong> Channel 36</strong> <em>“Special Functions”</em><br/><em>Add <strong>+1</strong> to the existing value as specified in the bubble (x?x).</em></p>\n<p><em>Example: origin value 01 or 1: change to 11 / origin value 00: change to 10</em> / <em>origin value 000: change to 010</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/11-Tuto-Vagcom-A3-8P-Check-des-Aiguilles-S3-ET-RS3-2ab59919.webp\"/></figure>","a3-8p-facelift-lock-the-cd-dvd-eject-button-on-the-rns-e":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose</strong>: To lock/unlock the RNS-E’s CD/DVD eject button.  </p>\n<p><em>Protection against theft of your navigation DVD.  </em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program. <strong><strong>37 – Navigation</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 67</strong> </em>then set the value to <strong>255</strong> <em>(Eject Button locked i.e. (Rental Car))</em></p>\n<p><em>Restart RNS-E.</em></p>\n<p>To eject the CD/DVD, set the value to <strong>0</strong> for normal use of the button, or <strong>1</strong> to eject it immediately.  </p>","a3-8p-facelift-maintain-decrease-drl-with-turn-signals":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> to maintain or reduce the intensity of the daytime running lights (DRL) with the indicators.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>8</strong>: </em><br/><em>Bit <strong>7</strong>: “Daytime Running Light (DRL) Desactivation while blinking active”.</em></p>\n<p>Uncheck to maintain intensity or Check to lower intensity.</p>\n<p><strong>For models from 2010 :</strong></p>\n<p><em>Byte <strong>15</strong>: </em><br/><em>Bit <strong>3</strong>: “Daytime Running Light (DRL) inactive with Turn Signals active”.</em></p>\n<p>Uncheck to maintain intensity or Check to lower intensity.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audittled-f128febf.webp\"/></figure>","a3-8p-facelift-microphone-sensitivity-adjustment":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> to adjust the intensity of the hands-free system’s microphone.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“77 – Telephone</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose Channel <strong>131</strong>.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose a value expressed in<strong>“dB</strong>” (default value<strong>“0 dB</strong>”) then validate.<br/></p>","a3-8p-facelift-needle-check":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> activates needle sweep when the car is started. (Needle Sweep)   </p>\n<p><strong><em>ATTENTION: Only for S3 and A3 Facelift compatible according to meter.</em></strong> </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>10 – Adaptation</strong> </p>\n<p><strong>5</strong> – Select<strong> Channel 36</strong> <em>“Special Functions”</em><br/><em>Add <strong>+1</strong> to the existing value as indicated in the bubble (xx?).</em></p>\n<p><em><em>Example: origin value 00 or 0: change to 01 or 1 / origin value 10: change to 11</em></em> / <em>origin value 000 : change to 001</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/11-Tuto-Vagcom-A3-8P-Check-des-Aiguilles-S3-ET-RS3-2ab59919.webp\"/></figure>","a3-8p-facelift-programming-a-remote-control":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to program the remote controls that will be used with the vehicle for central locking and unlocking.  </p>\n<p>⚠️ <strong>WARNING:</strong> This procedure does not allow you to program remote controls with the vehicle’s immobilizer.<br/>If your vehicle is equipped with a <strong>KESSY</strong> remote control <strong>(05 – Access/Ignition Authorization)</strong>, you cannot program a new remote control using this procedure.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>“09 – Cent. Elect.”</strong></strong>.”<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 01 ( </strong>“Remote Control Adaptation” from the drop-down list)</p>\n<p>Enter the number of keys to program, then click <strong>Save</strong>.<br/>Next, press the <strong>Unlock</strong> button on each remote control to be programmed for at least 1 second. The flashing lights will confirm the process.<br/>All keys must be programmed in a single session, one after the other.<br/>Programming all keys must not take longer than <strong>15 seconds</strong>.<br/>You can add up to <strong>7 remote controls</strong>. If the <strong>[Test]</strong> and/or <strong>[Save]</strong> buttons are grayed out and unclickable, the module likely has all 7 slots filled; delete the remote controls using the <strong>“Reset Remote Controls”</strong> tutorial.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/programmertelecommande-51bf4068.webp\"/></figure>","a3-8p-facelift-rear-lights-activated-with-daytime-running-lights-drl":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> Enables the rear lights to turn on when the daytime running lights (Scandinavian DRL) are activated. (Starting in 2010)  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1</strong>:<br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on <strong>“Coding – 07</strong>“.</p>\n<p><strong>5 –</strong> Byte <strong>18</strong>, Disable bit <strong>0</strong>, bit <strong>1</strong> and Enable bit <strong>2</strong></p>","a3-8p-facelift-remove-belt-alarm":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> to suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt (for models from 2010).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4 </strong>– Click on “<strong>Coding – 07 </strong>”.  </p>\n<p><em>Put<strong> 0</strong> in the penultimate digit of the code (00xxx<strong>?</strong>x)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-A3-8P-ed05618a.webp\"/></figure>\n<p>Example: 0000143 -&gt; 0000103</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","a3-8p-facelift-resetting-the-remote-controls":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> Resets the settings for all remote controls associated with the vehicle. </p>\n<p><strong>⚠️ WARNING:</strong> After completing this procedure, all remote controls will be deleted and will need to be reprogrammed using the <strong>“Program a Remote Control”</strong> tutorial <strong>.</strong><br/>If your vehicle is equipped with a <strong>KESSY</strong> remote control <strong>(05 – Access/Start Authorization)</strong>, you cannot delete the remote controls using this procedure.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong><strong>“09 – Cent. Elect.”</strong></strong></strong>.”<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 00</strong></p>\n<p><em>Set the value to <strong>0</strong> and save</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel00-caced031.webp\"/></figure>","a3-8p-facelift-speed-limit-display-rns-e":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose </strong>: to display the speed limit on the RNS-E navigation screen.  </p>\n<p><strong><em>ATTENTION: requires RNS-E version 193</em></strong></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong><br/></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on<strong>“37 – Navigation</strong>”.<br/><br/> 4<strong>– </strong>Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 17</strong> (Speed Display) then set the value according to the desired display. <br/><br/>Set the value according to the desired display<em><br/>0</em><em>– no option (display disabled)<br/></em> 1<em>– option on, off (speed display)<br/></em> 2<em>– option on, off, 5km/h, 10km/h, 15km/h, 20km/h (speed display + overrun warning)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-035-193-G_Module37_Adaptation_Channel17-6e590288.webp\"/></figure>\n<p><em>Don’t forget to restart the RNS-E, by pressing the power button for more than 40s.</em></p>","a3-8p-facelift-speedo-lighting":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose: </strong> Allows you to adjust the lighting of the hands and the dial.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>17 – Instruments.”</strong><br/><br/><strong>4 – </strong>Click on <strong>“Coding – 07” </strong> </p>\n<p><em>In the last digit of the coding (00xxxx<strong>?</strong>), enter the value according to the desired ignition:</em></p>\n<p><em><br/><strong>5</strong> = Hands off and dial off (ignition on, headlights off)<br/><strong>6</strong> = Hands on and dial off (ignition on, headlights off)<br/><strong>7</strong> = Hands off and dial on (ignition on, headlights off)<br/><strong>8</strong> = Dials on, needles off (ignition on, headlights off, with variable lighting)<br/><strong>9</strong> = Dials on, needles off (ignition off, headlights off, without variable lighting)?)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-A3-8P-ed05618a.webp\"/></figure>","a3-8p-facelift-start-stop-deactivation":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi A3 8P facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8p_facelift-dc093559.webp\"/></figure>\n<p><strong>Purpose:</strong> to disable Start and Stop completely.  <br/><br/><br/><strong><em>Only compatible with Gateway 7N0! Temperature deactivation method. </em></strong> <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on <strong>“Long Adaptation – 0A”</strong>.<br/><br/><strong>5</strong> – Select Channel<strong>“13</strong><br/><br/><strong>6</strong> – In new value, select<strong>“D02000</strong>” (default value = <strong>002000</strong>) then validate.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/gof6startstop-1024x528-699ec970.webp\"/></figure>","a3-8p-activate-advanced-comfort-menu-in-odb":"<p><strong>Purpose:</strong> activates the advanced comfort menu in the on-board computer, activating oil temperature and other functions.  </p>\n<p><em><strong>Modification only possible for vehicles with a 30-byte module.</strong></em> </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte 23: </em><br/><em>Bit 1: Check “</em>Advanced Comfort<em> Menu active”.</em></p>","a3-8p-activate-electrically-folding-mirrors-retrofit":"<p><strong>Purpose:</strong> to activate electrically folding mirrors after retrofitting (A3 facelift mirror and window motor assembly).  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“42-Driver door</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then <em>Add <strong>4096</strong> to the existing value</em>…<br/></p>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then <em>Add <strong>4096</strong> to the existing value.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7119-4840248c.webp\"/></figure>","a3-8p-activate-fog-lights-when-reversing":"<p><strong>Purpose</strong>: Allows the rear fog lamps to be used when reversing, giving more light and safety when maneuvering in the dark.  </p>\n<p><em><strong>Modification only possible for vehicles with a 30-byte module.</strong></em></p>\n<p><strong>Procedure</strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><strong>6 –</strong> <em>Byte <strong>26</strong>: </em><br/><em>Check Bit <strong>6</strong></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/antibrouillard-marche-arriere-a3-8p-e0a81b13.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rearfoglightaudia38p-be6fbd1f.webp\"/></figure>","a3-8p-activate-mood-lighting":"<p><strong>Purpose</strong>: to activate ambient foot lighting while driving. The footwell lights in the MFA appear in the Light &amp; Visibility menu, where brightness can also be adjusted.  (from 2006)  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong> “Long Coding Helper”</strong>.</p>\n<p><strong>5</strong> – Choose <em>Byte <strong>12</strong> </em><br/><em>Check Bit <strong>5</strong></em></p>","a3-8p-activate-rear-fog-lights-when-braking":"<p><strong>But</strong> : Permet d’utiliser les feux antibrouillard arrière comme feux de position et feux stop. </p>\n<p><em><strong>This modification is only possible for vehicles with a 30-byte module.</strong></em></p>\n<p><strong>Procedure</strong>: <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 (fog lights/brake lights):</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>6 –</strong> <em>Byte <strong>21</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Rear Fog Light as Brake Light</em> ”</p>\n<p><strong>Line 2 (fog lights/parking lights):</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>Byte 10</strong>: Enter the value<strong> 22</strong> in the ” <strong>Dec</strong>” field</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rearfoglightaudia38p-be6fbd1f.webp\"/></figure>","a3-8p-activate-turn-signals-in-us-mode":"<p><strong>Purpose:</strong> to activate US indicators. (A3 8P phase 1 only)   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong> </p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>Byte 7</strong>: Set value<strong> 32</strong> in <strong>Dec</strong> box (value in % of intensity, origin: 0)</p>\n<p>Decimal examples shown in yellow in the image:<br/>14 (corresponds to a 20% variation in the indicator lights)<br/>1E (corresponds to a 30% variation in the indicator lights)<br/>28 (corresponds to a 40% variation in the indicator lights)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3C0-937-049-Q_Module09_Byte7-16502f21.webp\"/></figure>\n<p><em>For A3 8P Facelift, activation is only possible with the VCP.</em></p>","a3-8p-activating-the-multifunction-steering-wheel-retrofit":"<p><strong>Purpose </strong>: to activate the multifunction steering wheel for retrofitting.  <strong> </strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>16 – Multifunction steering wheel</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><strong>5</strong> – x<strong>?</strong>xxx: Steering wheel variant<br/><br/>The following options (replace with ?):<br/><br/>0 – steering wheel without multifunction<br/>1 – 3-spoke steering wheel (without multifunction)<br/>2 – 4-spoke multifunction steering wheel for radio control<br/>3 – 4-spoke multifunction steering wheel for radio/telephone control<br/>4 – 4-spoke multifunction steering wheel for radio/telephone/cond.</p>","a3-8p-ambient-lighting-intensity":"<p><strong>Purpose:</strong> Used to adjust ambient lighting intensity.  </p>\n<p><strong>Procedure</strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 05</strong> (Footwell Lightning Dimming)  </p>\n<p><strong>6 –</strong> Select intensity from 20 to 100% (in 1% increments)</p>","a3-8p-automatic-closing-of-windows-and-roof-in-case-of-rain":"<p><strong>Purpose</strong>: Automatically closes the windows and sunroof when it rains. </p>\n<p>The vehicle must be locked using the remote control for this to work. </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitregolf561-c90da3e5.webp\"/></figure>\n<p><strong>5</strong> – Select module “2” and click ” <strong>Long Coding Helper</strong> “:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitregolf56-9439cbb9.webp\"/></figure>\n<p><strong>6</strong> – In the window that appears, select byte 0 and check bit 2, <strong>“Rain Closing active</strong>,” to enable the windows and roof to close when it rains:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com-Fermeture-Automatique-des-vitres-5-d61c5dd9.webp\"/></figure>\n<p>7 – After completing this step, click on the “Exit” menu</p>\n<p> Then click “OK”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com-Fermeture-Automatique-des-vitres-7-353fb01b.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click <strong>“46 – Central Conv”</strong> </p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5 –</strong> Then click <strong>” <strong>Long Coding Helper</strong> “</strong> </p>\n<p><em>Byte 9: </em><br/><em>Bit 1: Check “Rain Closing (0 = nonrecurring / 1 = permanent)” </em><br/><em>Bit 2: Uncheck “Comfort Closing via Rain Light Sensor (Rain Closing) inactive” </em> </p>","a3-8p-automatic-door-locks":"<p><strong>Purpose:</strong> to set automatic door locking from 15km/h.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 04</strong></p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres_vw-auto-loc-ce03b1da.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Auto-Lock (automatic locking from 15 km/h)”. </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","a3-8p-automatic-door-unlocking":"<p><strong>Purpose:</strong> to set automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Canal 05</strong></p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw-door-unlock-798a1163.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong><em>If the adaptation channel is not activated.</em></strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte<strong> 0</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Auto-Unlock (unlocking after removing key from ignition)”. </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","a3-8p-automatic-headlight-activation":"<p><strong>Purpose:</strong> Automatically switches on lights according to brightness.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”</p>\n<p><strong>5</strong> – Select <strong>Channel 07, </strong><em>set to<strong> 1 </strong>to activate the option.</em></p>","a3-8p-automatic-headlight-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_auswahl-steuergerate-rls-wws-bord-c6f10e6e.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","a3-8p-aux-in-socket-activation-retrofit":"<p><strong>Purpose </strong>: to activate the AUX-IN input. After installing the jack plug on the car radio connector or a Bluetooth kit (RNS-E or Generation II+ Concert, Chorus and Symphony), you can select AUX-IN in Source. For a BT module, if you have the AMI option, deactivate it.   (Retrofit)</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 (For RNS-E !) :</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“37 – Navigation</strong>” .<br/><br/><strong>4 </strong>– Click on<strong>“Codage- 07</strong>”.</p>\n<p><strong>5</strong> – Modify the penultimate digit by adding <strong>4</strong>(e.g. replace <strong>xxxxx1x</strong>with <strong>xxxxx5x</strong>). </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_stg37_navi_codierung_auxin-f8795b14.webp\"/></figure>\n<hr/>\n<p><strong>Line 2 (For Generation II+ Concert, Chorus and Symphony</strong>)<strong>:</strong><br/><br/> 3 – Click on ” <strong>Select</strong> ” then click on<strong>“56 – Radio</strong>” .<br/><br/> 4<strong>– </strong>Click on<strong>“Codage- 07</strong>“.  </p>\n<p>5 – Modify the second digit by adding <strong>+4</strong> (0<strong>?</strong>x0xxx): <strong><br/><br/>+1 = Analog input (AUX)</strong><br/>+2 = Multifunction steering wheel<br/>+4 = Telephone</p>","a3-8p-auxiliary-heater":"<p><strong>Purpose</strong>: to activate auxiliary heating.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>17 – Instruments.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Adaptation-10.”</strong></p>\n<p><strong>5</strong> – Select <strong>Channel 18</strong></p>\n<p><em>Change the value with</em></p>\n<p><em>First digit: Warm-up</em><br/><em>0 : No heating</em><br/><em>1 : Engine warm-up</em></p>\n<p><em>Second digit: Type of auxiliary heating</em><br/><em>0: No auxiliary heating</em><br/><em>1: Auxiliary heating and ventilation installed</em><br/><em>2: Auxiliary heating and ventilation switched off when engine off</em><br/><em>3: Auxiliary fan installed only</em><br/><em>4: Auxiliary fan installed only, off when engine off</em></p>","a3-8p-change-odb-language":"<p><strong>Purpose </strong>: Selects the language used in the on-board computer.  </p>\n<p><strong>(Modification only possible on Mid/High range models)</strong> </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong></p>\n<p><em>Change the value according to the desired language</em></p>\n<p><em>00001 – German</em><br/><em>00002 – English</em><br/><em>00003 – French</em><br/><em>00004 – Italian</em><br/><em>00005 – Spanish</em><br/><em>00006 – Portuguese / Brazilian</em></p>","a3-8p-comfort-blinker":"<p><strong>Purpose:</strong> to set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4 – </strong> Click “<strong>Adaptation – 10</strong>.”</p>\n<p><strong>5 </strong>– Select<strong>“Comfort Turn Signal”</strong> from the drop-down list </p>\n<p>Choose a value between 1 and 5 for the number of flashes</p>","a3-8p-coming-home-time-setting":"<p><strong>Purpose:</strong> Set the length of time the headlights remain on after the car is locked.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 01</strong> (Coming-Home Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>0 to 60 sec</strong> (in 1sec increments).</p>","a3-8p-corner-lights-activation":"<p><strong>Purpose</strong>: to activate cornering lights with fog lamps.  </p>\n<p><em><strong>Modification only possible for vehicles with a 30-byte module.</strong></em> </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte<strong> 23</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Internal Turn Light Control Algorithm active”.</em><br/><em>Bit <strong>3-4</strong>: Select “08 Turn Lights via fog lights” from the drop-down list</em></p>","a3-8p-correction-of-odb-consumption-display":"<p><strong>Purpose</strong>: to correct the fuel consumption display on the on-board computer.  </p>\n<p><strong>Modification only possible on Mid/High range models</strong>. <br/><em>Note: modifications affect the display of instantaneous consumption, average consumption and fuel quantity.</em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on <strong>“17 – Instruments”</strong>. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation- 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> <em>“Consumption Correction”.</em></p>\n<p><em>Adjust consumption correction factor between 85% and 115%.</em> <em>(base value: 100)</em></p>\n<p><em>Example 1: Calculation based on volume per distance (e.g. l/100 km): DIS: 9.3 l/100 km. Actual: 9.8 l/100 km. (100, 9,8 / 9,73 ? 105,38) Channel 3 will be changed from 100 to 105 <br/>Example 2: Calculation based on volume distance (e.g. MPG is: DIS: 23 MPG. Actual: 24 MPG. (100, 23/24 and 95.83) Channel 3 will be changed from 100 to 96</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/correction-consommation-odb-d51db18e.webp\"/></figure>","a3-8p-cruise-control-activation-retrofit":"<p><strong>Purpose </strong>: to activate GRA cruise control (retrofit). </p>\n<p><strong><strong><strong>Modification only possible after retrofitting cruise control switch </strong>and <a href=\"https://wiki.ross-tech.com/wiki/index.php/Steering_Wheel_Control_Module_Versions\" rel=\"noopener\" target=\"_blank\">check that your multifunction steering wheel is compatible (midline or highline)</a>.</strong></strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>01 – Motor</strong> “.<br/><br/><strong>4 </strong>– Click on ” <strong>Coding II (11) or Login 11</strong> “. </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur1-1c279499.webp\"/></figure>\n<p><strong>5</strong> – Then enter code <strong>11463</strong>, then <strong>OK</strong> (Do It!)</p>\n<p>The code 11463 is used to <strong>activate</strong> the controller, to <strong>deactivate</strong> it if necessary the code is 16167.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur2-6871f13e.webp\"/></figure>\n<p><strong>Line 2:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>16 – Multifunction handwheel</strong>“.<br/><br/>4<strong>– </strong>Click on ” <strong>Coding – 07</strong>“. </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur4-1024x512-f581d6bc.webp\"/></figure>\n<p>0xxxx? X<br/>Options<br/>0 = no on-board computer, no cruise control.<br/>1 = on-board computer, no cruise control.<br/>2 = no on-board computer, cruise control.<br/>4 = on-board computer, cruise control. </p>\n<p><strong>Line 3:</strong><br/><br/>3 – Click on ” <strong>Select”, then click on ” Select</strong> “. <strong><strong>01 – Engine</strong></strong> ” .<br/><br/>4 – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.</p>\n<p><strong>5 – </strong>Select byte<strong>“5</strong>“<br/>Check bit<strong>“5</strong>” Cruise Control System (CCS) installed</p>\n<p>Or byte <strong>6</strong> bit <strong>0</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur5-1024x491-af7739d1.webp\"/></figure>","a3-8p-deactivate-brake-pad-warning-light":"<p><strong>Purpose</strong>: Allows you to disable the brake pad wear warning light on the OBD (On-Board Diagnostics) system, for example, for brake pads without a sensor or if the sensor is malfunctioning / Brake Pad Warning Light Deactivation. </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>17 – Instruments.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – <em>The third and fourth digits of the code (xx<strong>??</strong>x0x) are used to change the settings for the Instrument module. To turn off the windshield washer light, subtract <strong>1</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial code (with the windshield washer light on) is: <strong>0023103</strong></p>\n<p>To turn off the windshield washer light, simply recode it as follows: <strong>0022103 </strong><em>(23 – 01 = 22)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant-frein-d4619ec9.gif\"/></figure>","a3-8p-deactivate-rear-wiper-when-reversing":"<p><strong>Purpose:</strong> to deactivate automatic activation of the rear windshield wiper during reversing when the front windshield wipers are operating.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em><strong>Byte 1 :</strong></em><br/><em><strong>Bit 7 </strong>: Uncheck “Rear Wiper with Front Wiper continiously active”.</em></p>\n<p><em><strong>Byte 2 : </strong></em><br/><em><strong>Bit 0</strong>: Uncheck “Rear Wiper with Front Wiper intermitent active”.</em></p>\n<p><em>OR</em> Byte <strong>07</strong>: Uncheck Bit <strong>7</strong></p>","a3-8p-deactivate-windshield-washer-indicator":"<p><strong>Purpose</strong>: to deactivate the windshield washer indicator on the ODB (on-board computer, for A3 8P phase 1 only).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> –  <em>The third and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To remove the ice-washer indicator, subtract <strong>4</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial coding (with washer indicator) is: <strong>0025103</strong></p>\n<p>To remove the windscreen washer indicator, simply recode as follows: <strong>0021103 </strong><em>(25 – 04 = 21)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglaceaudia38p-d44c3cb7.webp\"/></figure>","a3-8p-defrost-time-setting":"<p><strong>Purpose:</strong> to set the operating time for mirror and rear window defrosting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong> then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> (Rear Window &amp; Outside Mirror Heater Activation Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>1 to 254 min</strong> (in 1 min increments).</p>","a3-8p-delete-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt. (A3 8P1)  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> –  <em>The third and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To suppress the belt alarm, subtract <strong>2</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial coding (with belt alarm) is: <strong>0023103</strong></p>\n<p>To delete the belt alarm, simply recode as follows: <strong>0021103 </strong><em>(23 – 02 = 21)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","a3-8p-disable-plate-light-control-odb-led-error":"<p><strong>Purpose:</strong> Disables license plate light control. Useful when installing LED bulbs without resistance or for error prevention.   </p>\n<p><em><strong>Modification only possible for vehicles with a 30-byte module.</strong></em> </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>18</strong>: </em><br/><em>Bit <strong>0</strong>: Uncheck “Cold Diagnosis Licence Plate Lights active”.</em></p>","a3-8p-display-the-speed-on-the-audi-concert-ii":"<p><strong>Purpose:</strong> Adds a “Driving School” view to the Audi Concert II+ radio that displays your speed (also ideal for supervised driving) <br/><br/><br/><strong>Instructions:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>56 – Radio</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Channel 2</strong>” “Driving School Function/Time Display”<br/><br/><strong>7</strong> – Set the value to <strong>1</strong>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RCD300_Module56_Channel02-3c0994f0.webp\"/></figure>\n<p>To activate the function, select SETUP -&gt; Speed -&gt; On</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_concert_2_plus-444b7cdf.webp\"/></figure>","a3-8p-door-lock-confirmation-key":"<p><strong>Purpose: </strong> Allows you to configure the door lock confirmation when using the key.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.<br/><br/><strong>4 – </strong> Click “<strong>Adaptation – 10</strong>“</p>\n<p><strong>Channel 11</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2: </strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit<strong> 0</strong>: Check “Locking Confirmation (Blink) via Door Locks” (confirmation with flashing lights)</em><br/><em>Bit <strong>1</strong>: Tick “Locking Confirmation (Horn) via Door Locks” (confirmation with beep/horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/locking_196-096e4b1a.webp\"/></figure>","a3-8p-door-lock-confirmation-remote-control":"<p><strong>Purpose: </strong> Allows you to configure the door lock confirmation when using the remote control. </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 10</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vagcom-golf5-e5c80be6.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Locking Confirmation (Blink) via Remote Control” (confirmation with flashing lights)</em><br/><em>Bit <strong>3</strong>: Tick “Locking Confirmation (Horn) via Remote Control” (confirmation with Beep/Horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/locking_196-096e4b1a.webp\"/></figure>","a3-8p-door-unlock-confirmation-remote-control":"<p><strong>Purpose </strong>: to set the door unlock confirmation when using the remote control.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 07</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>10 </strong>: </em><br/><em>Bit <strong>2</strong>: Check “Unlocking Confirmation (Blink) via Remote Control” (confirmation with flashing lights)</em><br/><em>Bit <strong>3</strong>: Tick “Unlocking Confirmation (Horn) via Remote Control” (confirmation with Beep/Horn)</em></p>","a3-8p-door-unlocking-confirmation-key":"<p><strong>Purpose: </strong> Allows you to configure the door unlock confirmation when using the key.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 08</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>10</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Unlocking Confirmation (Blink) via Door Locks” (confirmation with blinking lights)</em><br/><em>Bit <strong>1</strong>: Check “Unlocking Confirmation (Horn) via Door Locks” (confirmation with a beep or horn)</em></p>","a3-8p-drain-interval-reset":"<p><strong>Purpose</strong>: Resets the oil change interval. </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>17 – Instruments.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Adaptation-10.”</strong></p>\n<p><strong>5</strong> – Select <strong>Channel 02</strong></p>\n<p><em>Set the value to <strong>0</strong></em></p>\n<p>To reset the drain interval completely and automatically, follow the steps below.</p>\n<p>Click on “Reset maintenance” on the VCDS home screen.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/accueil_vcds-0c100c7a.webp\"/></figure>\n<p>Wait for the following window to open and select “reset service” from the drop-down list, then click on “Start operation”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/reset_entretien_vcds-b31903a6.webp\"/></figure>","a3-8p-error-counter-for-electrical-management":"<p><strong>Purpose:</strong> Set the number of errors allowed before generating an alert.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4 – </strong> Click “<strong>Adaptation – 10</strong>.”</p>\n<p><strong>5 </strong>– Select <strong>Channel 06 </strong> </p>\n<p>Choose a value between 0 and 3 (default: 0)</p>","a3-8p-facelift-rear-lights-retrofit":"<p><strong>Purpose:</strong> Enables the LED facelift taillights for the Audi A3 8P Sportback (5-door) after replacing the Phase 1 halogen taillights with LED facelift taillights (retrofit).</p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition turned off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<ul>\n<li>Byte 09 on HEX 00</li>\n<li>Byte 10 on HEX 00</li>\n<li>Byte 12 on HEX 36</li>\n<li>Byte 19 6th binary digit at 0</li>\n<li>Byte 21 Binary 4th digit to 1 (option see description)</li>\n</ul>\n<p><em><strong>Description:</strong></em></p>\n<ul>\n<li>Byte 09 disables the brake light’s flashing function as a taillight. (Therefore, only the LED strip lights up when the parking lights and low beams are on.) </li>\n<li>By adjusting byte 12, you can precisely match the brightness of the outdoor LED strip to that of the indoor lights (at least if a Kufatec adapter with a 100-ohm resistor is installed).</li>\n<li>Byte 19 disables the cold-start diagnostic for the parking lights. This means that the LED strip does not flash when the ignition is turned on. </li>\n<li>Byte 21 means that the rear fog lights also turn on when you brake (so this is purely cosmetic—you’ll have to decide for yourself if that’s important to you!)</li>\n</ul>","a3-8p-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates brake lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>17</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Emergency Brake Flash Light active”.</em></p>","a3-8p-fold-down-mirrors-with-ignition-off-and-door-open":"<p><strong>Purpose </strong>: Allows mirrors to be folded down even after the ignition has been switched off and a door opened.  </p>\n<p><em>(Also enables windows and sunroof to be closed)</em> </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>46 – Comfort Module</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><em>Byte 6 : </em><br/><em>Bit 7: Uncheck “Power Windows/Sunroof disabled after door Opening”.</em></p>","a3-8p-headlamp-washer-duration-setting":"<p><strong>Purpose:</strong> Allows you to set how long the headlight washers remain activated.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong> (Headlight Washer Activation Time)  </p>\n<p><strong>6</strong> – Select a duration between <strong>50 and 10,000 ms</strong> (in 50-ms increments).</p>","a3-8p-leaving-home-duration-setting":"<p><strong>Purpose:</strong> to set the length of time the headlights remain on after the car is unlocked.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</strong> </p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 02</strong> (Leaving-Home Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>0 to 60 sec</strong> (in 1sec increments).</p>","a3-8p-lights-on-automatically-in-rain":"<p><strong>Purpose:</strong> to automatically turn on the lights when it’s raining and the wipers have been triggered.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Bit <strong>1: </strong> Tick “Rain Light Function Active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","a3-8p-modify-power-steering-hardness":"<p><strong>Purpose </strong>: to adjust the hardness of the power steering for a softer or harder steering wheel.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“44 – Direction assistée” / “44-steering assist.</strong><br/><br/><strong>4 </strong>– Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5 – </strong>Select<strong> Channel 1 </strong>, <em>set a value between<strong> 1</strong> and <strong>15</strong> depending on your hardness preference</em>.</p>\n<p><strong>Or Line 2: (If channel 1 is unavailable)</strong>:<br/><br/> 3 – Click on<strong>“Select</strong>” then click on<strong>“44 – Direction assistée” / “44-steering assist.”</strong><br/><br/> 4<strong>– </strong> Click on<strong>“Coding – 07</strong>”.</p>\n<p><strong>5 – </strong>Select :</p>\n<ul>\n<li>xxx1x for smooth steering</li>\n<li>xxx2x for sports management</li>\n<li>xxx3x for hard steering</li>\n<li>xxx4x for harder steering</li>\n<li>xxx5x for very hard steering</li>\n</ul>","a3-8p-one-touch-window-closing":"<p><strong>Purpose</strong>: to activate closing and opening of the windows and sunroof with the remote control <strong>WITHOUT </strong>remaining pressed until the windows are completely closed.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition turned off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition and launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Central Conv.”</strong></p>\n<p><strong>4</strong> – Click ” <strong>Encoding 07</strong>,” then “Long Coding Helper”</p>\n<p><strong>5 –</strong> <em>Byte 6: </em><br/><em>Bit 6: Check “Comfort Function Automatic Closing”</em></p>\n<ul>\n<li>Uncheck “Comfort function power windows/sunroof via remote control inactive”.</li>\n<li>Check “Comfort opening power windows via remote control active”.</li>\n<li>Check “Comfort closing power windows via remote control active”.</li>\n<li>Check “Closing sunroof via remote control active” (sunroof)</li>\n</ul>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ComfortConv-byte6-9f2c129f.webp\"/></figure>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Comfort Module.”</strong><br/><br/><strong>4 – </strong>Click “ <strong>Adaptation – 10”</strong> </p>\n<p><strong>Channel 17</strong> (Comfort function)</p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_0944-1024x741-ec4d5180.webp\"/></figure>\n<p><em>Pressing the remote control’s close button for 3 seconds will first lock the doors and then close the windows, without having to keep the button pressed until they are fully closed</em>.</p>","a3-8p-outdoor-temperature-display-on-odb":"<p><strong>Purpose:</strong> to add an external temperature display to the on-board computer.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 20</strong>”.<br/><br/><strong>5</strong> – Set last digit to <strong>1</strong> (xx1)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-920-930-C_Module17_Adaptation_Channel20-ca671648.webp\"/></figure>","a3-8p-programming-a-remote-control":"<p><strong>Purpose:</strong> Allows you to program the remote controls that will be used with the vehicle for central locking and unlocking.  </p>\n<p>⚠️ <strong>WARNING:</strong> This procedure does not allow you to program the remote controls with the vehicle’s immobilizer.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 01 ( </strong>“Remote Control Adaptation” from the drop-down list)</p>\n<p>Enter the number of keys to program, then click <strong>Save</strong>.<br/>Next, press the <strong>Unlock</strong> button on each remote control to be programmed for at least 1 second. The flashing lights will confirm the procedure.<br/>All keys must be programmed in a single session, one after the other.<br/>Programming all keys must not take longer than <strong>15 seconds</strong>.<br/>You can add up to <strong>4 remote controls</strong>. If the <strong>[Test]</strong> and/or <strong>[Save]</strong> buttons are grayed out and unclickable, the module likely has all 4 slots filled; delete the remote controls using the <strong> “Reset Remote Controls”</strong> tutorial.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel01-10148edb.webp\"/></figure>","a3-8p-radio-time-synchronization":"<p><strong>Purpose</strong>: to set the time synchronization interval for the radio.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation- 10</strong>” .</p>\n<p><strong>5</strong> – Select <strong>Channel 19</strong></p>\n<p><em>Set synchronization interval between 1 and 50 min ( 0 disables function )</em></p>","a3-8p-resetting-the-remote-controls":"<p><strong>Purpose:</strong> Resets the settings for all remote controls associated with the vehicle.</p>\n<p><strong>⚠️ WARNING:</strong> After completing this procedure, all remote controls will be deleted and will need to be reprogrammed using the <strong>“How to Program a Remote Control”</strong> tutorial <strong>.</strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 00</strong></p>\n<p><em>Set the value to <strong>0</strong> and save</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel00-caced031.webp\"/></figure>","a3-8p-retrofit-heated-mirrors":"<p><strong>Purpose:</strong> to activate heated/defrosting mirrors after retrofitting. <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“42-Driver door</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then <em>Add <strong>32</strong> to the existing value</em>…<br/></p>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then <em>Add <strong>32</strong> to the existing value.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7119-4840248c.webp\"/></figure>","a3-8p-selective-door-unlocking":"<p><strong>Purpose </strong>: Used to set up selective door unlocking. </p>\n<p>When unlocking the vehicle, only the driver’s door is unlocked. To unlock all doors, press the remote control’s unlock button twice.   </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 03</strong></p>\n<p><em>Set value to 1</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte 0 : </em><br/><em>Bit 0 : Check “Selective Central Locking (Single Door Opening)”. </em> </p>","a3-8p-show-hidden-menu-climatronic":"<p><strong>Purpose: Displays </strong>the Climatronic hidden menu.  </p>\n<p><strong>Display the instantaneous digital speed? It’s possible! </strong>  You don’t need to use your VCDS VAG-COM cable for this tutorial.  </p>\n<p><strong>What is it used for?</strong></p>\n<p>In the hidden Audi Climatronic menu, you can easily access secret diagnostic readings such as battery voltage, vehicle speed, engine RPM, sensor readings, system DTCs, and much more.</p>\n<h3>Audi Climatronic hidden menu procedure</h3>\n<p>To display some of the car’s operating parameters on the air-conditioning display:</p>\n<ol>\n<li>Simultaneously press the air recirculation button and the upward ventilation button.</li>\n<li>The display shows “1C” (channel 1 is the default).</li>\n<li>Use the temperature change knob to select the desired function. Press “+” to access the upper channel and “-” to access the lower channel. </li>\n<li>For example, for real-time engine oil temperature, you need to display channel 51 (51C on the screen).</li>\n<li>Confirm the function by pressing the air recirculation button.</li>\n<li>The selected channel’s information is then displayed on the climate control screen.</li>\n</ol>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatisation_1-5803fa4a.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatisation_2-f3440ecb.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatisation_3-e0877cf3.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatisation_4-c24dbc07.webp\"/></figure>\n</figure>\n<h3>List of Hidden Channels in the Menus</h3>\n<figure><table><tbody><tr><td>1</td><td>System error</td></tr><tr><td>2</td><td>Virtual sensor value</td></tr><tr><td>3</td><td>Inside console sensor value</td></tr><tr><td>4</td><td>Outside temperature value – water tank sensor</td></tr><tr><td>5</td><td>Outside temperature value – bumper sensor</td></tr><tr><td>6</td><td>Lower supply sensor value</td></tr><tr><td>7</td><td>Front air sensor value</td></tr><tr><td>8</td><td>Display check</td></tr><tr><td>9</td><td>Digital value of temperature valve return potentiometer</td></tr><tr><td>10</td><td>Digital temperature valve setpoint</td></tr><tr><td>11</td><td>Digital value of air-conditioning valve return potentiometer</td></tr><tr><td>12</td><td>Digital air conditioning valve setpoint</td></tr><tr><td>13</td><td>Digital value of foot valve/defrost return potentiometer</td></tr><tr><td>14</td><td>Digital foot valve/defrost setpoint</td></tr><tr><td>15</td><td>Digital value of supply air damper return potentiometer</td></tr><tr><td>16</td><td>Digital supply air damper setpoint</td></tr><tr><td>17</td><td>Speed in km/h</td></tr><tr><td>18</td><td>Ventilation voltage value (Volts)</td></tr><tr><td>19</td><td>Ventilation voltage setpoint (Volts)</td></tr><tr><td>20</td><td>Compressor voltage value (Volts)</td></tr><tr><td>21</td><td>Number of very low voltage events (non-volatile)</td></tr><tr><td>22</td><td>High-pressure switch status</td></tr><tr><td>23</td><td>Number of high-pressure events (volatile)</td></tr><tr><td>24</td><td>Number of high-pressure events (non-volatile)</td></tr><tr><td>25</td><td>A/D value Kick-Down switch</td></tr><tr><td>26</td><td>A/D value warm indicator light</td></tr><tr><td>27</td><td>Engine speed</td></tr><tr><td>28</td><td>Compressor speed</td></tr><tr><td>29</td><td>Encoding</td></tr><tr><td>30</td><td>Software Version</td></tr><tr><td>31</td><td>Software index</td></tr><tr><td>32</td><td>Error counter potentiometer temperature valve</td></tr><tr><td>33</td><td>Meter errors potentiometer air conditioning valve</td></tr><tr><td>34</td><td>Meter errors potentiometer feet/defrost valve</td></tr><tr><td>35</td><td>Error meter potentiometer supply air damper</td></tr><tr><td>36</td><td>Cold stop temperature valve</td></tr><tr><td>37</td><td>Hot stop temperature valve</td></tr><tr><td>38</td><td>Air conditioning damper stop closed</td></tr><tr><td>39</td><td>Air conditioning damper stop open</td></tr><tr><td>40</td><td>Foot valve/defrost stop</td></tr><tr><td>41</td><td>Foot stop foot valve/defrost</td></tr><tr><td>42</td><td>Supply air damper stop open</td></tr><tr><td>43</td><td>Supply air damper stop closed</td></tr><tr><td>44</td><td>Rolling cycle counter</td></tr><tr><td>45</td><td>Calculated indoor temperature (Ninc)</td></tr><tr><td>46</td><td>Filtered outdoor temperature (°C)</td></tr><tr><td>47</td><td>Unfiltered outdoor temperature (°C)</td></tr><tr><td>48</td><td>ECOR</td></tr><tr><td>49</td><td>Coolant temperature</td></tr><tr><td>50</td><td>Stopping time in minutes</td></tr><tr><td>51</td><td>Engine oil temperature in °C</td></tr><tr><td>52</td><td>Compressor stop conditions</td></tr><tr><td>53</td><td>Display active electrical outputs: compressor, room air valve, water valve</td></tr><tr><td>54</td><td>Control indication number</td></tr><tr><td>55</td><td>Outside temperature in °C</td></tr><tr><td>56</td><td>Virtual indoor sensor °C</td></tr><tr><td>57</td><td>Indoor console sensor °C</td></tr><tr><td>58</td><td>Water tank temperature °C</td></tr><tr><td>59</td><td>Bumper temperature °C</td></tr><tr><td>60</td><td>Lower supply sensor temperature</td></tr><tr><td>61</td><td>Temperature of front air sensor</td></tr><tr><td>62</td><td>Solar intensity W/m-1</td></tr><tr><td>63</td><td>Filtered solar intensity W/m-1</td></tr><tr><td>64</td><td>Delta ventilation increase</td></tr><tr><td>65</td><td>Delta transition air conditioning dampers</td></tr><tr><td>66</td><td>Cadence time /1.6 sec</td></tr><tr><td>67</td><td>Cold start correction</td></tr><tr><td>68</td><td>Maximum setpoint P and I components</td></tr><tr><td>69</td><td>Blower sensor value feet (cnts)</td></tr><tr><td>70</td><td>Foot blow sensor setpoint (cnts)</td></tr><tr><td>71</td><td>Difference (Epsilon)</td></tr><tr><td>72</td><td>Share (+ heating / – cooling)</td></tr></tbody></table></figure>","a3-8p-synchronized-mirror-adjustment":"<p><strong>Purpose </strong>: Activates synchronous adjustment of exterior mirrors. When the mirror setting is changed, the second mirror is moved synchronously.   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>”.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on “<strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>09</strong>: </em> Check Bit <strong>6</strong> <br/></p>","a3-8p-activate-daytime-running-lights-with-fog-lamps-drl":"<p><strong>Purpose</strong>: Allows fog lights to be used as daytime running lights. (Starting in 2006)   </p>\n<p><strong>Procedure</strong>: <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>6 –</strong> <em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4:</strong> Check “Daytime Running Lights (North America)”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/scandinavie_194-c7df4fa8.webp\"/></figure>\n<p><strong>7 – </strong> <em>Byte <strong>17: </strong> </em><br/><em>Bit <strong>4: </strong> Check “Daytime Running Light with dimmed Low Beam” (or “Daytime Running Light via Fog Lights,” depending on your version of VCDS)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ab_975-e7b60077.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/veilleusejour3-c639151f.webp\"/></figure>\n<p><strong>8-</strong> Adjusting the fog light intensity (from 1% to 99%)</p>\n<p><em>Byte <strong>20: </strong></em><br/><em>Change the value in the <strong>Dec</strong> box</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/VagComByte20-adce5646.webp\"/></figure>","a3-8p-open-sky-comfort-roof-closure":"<p><strong>Purpose</strong>: to activate the comfort closing function of the Open Sky panoramic sunroof. When the vehicle is locked/closed, the Open Sky roof closes automatically. </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>46 – Central Conv</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>” then “Long Coding Helper”</p>\n<p><strong>5 –</strong> Byte <strong>04</strong>: Check Bit <strong>5</strong> (eFH comfort shutdown via FFB active)</p>\n<p>Byte <strong>05</strong>: Check Bit <strong>5</strong> (SAD comfort closure via FFB active)</p>"};
